mapper.select:
SELECT  FROM inventory_transactions
WHERE tenant_id = #{tenantId} AND request_id = #{requestId}
FOR UPDATE

mapper.update:
UPDATE warehouse_stock SET quantity = quantity + #{quantity}
WHERE tenant_id = #{tenantId} AND warehouse_id = #{warehouseId} AND spare_part_id = #{sparePartId}
  AND quantity <= 99999999999.999 - #{quantity}

UPDATE work_order_parts wp
JOIN work_orders wo ON wo.id = wp.work_order_id
JOIN spare_parts sp ON sp.id = wp.spare_part_id AND sp.tenant_id = wo.tenant_id
SET wp.returned_quantity = wp.returned_quantity + #{quantity}
WHERE wo.tenant_id = #{tenantId} AND wp.work_order_id = #{workOrderId} AND wp.spare_part_id = #{sparePartId}
  AND wp.returned_quantity <= wp.issued_quantity - #{quantity}
